-- Versioned internal read contracts. Mutations must use owner commands.
CREATE SCHEMA IF NOT EXISTS pulse_read;
CREATE VIEW pulse_read.action_dependencies_v1 WITH (security_barrier = true) AS SELECT action_dependency_id, project_id, action_dependency_type_id, name, status, metadata_json, created_by_user_id, created_at, updated_at, company_id FROM public.action_dependencies OFFSET 0;
CREATE VIEW pulse_read.action_dependency_types_v1 WITH (security_barrier = true) AS SELECT action_dependency_type_id, dependency_type_key, display_name, provider_key, auth_schema_json, metadata_schema_json, created_at, updated_at FROM public.action_dependency_types OFFSET 0;
CREATE VIEW pulse_read.client_projects_v1 WITH (security_barrier = true) AS SELECT client_id, project_id, company_id FROM public.client_projects OFFSET 0;
CREATE VIEW pulse_read.clients_v1 WITH (security_barrier = true) AS SELECT client_id, company_id, status, name, full_name, created_at, updated_at, email, telegram, source, search_vector FROM public.clients OFFSET 0;
CREATE VIEW pulse_read.companies_v1 WITH (security_barrier = true) AS SELECT company_id, slug, name, status, created_at, updated_at, created_by_user_id FROM public.companies OFFSET 0;
CREATE VIEW pulse_read.company_memberships_v1 WITH (security_barrier = true) AS SELECT company_id, user_id, role, created_at FROM public.company_memberships OFFSET 0;
CREATE VIEW pulse_read.email_templates_v1 WITH (security_barrier = true) AS SELECT email_template_id, subject_template, body_template, body_format FROM public.email_templates OFFSET 0;
CREATE VIEW pulse_read.message_templates_v1 WITH (security_barrier = true) AS SELECT message_template_id, body_template, body_format, metadata_json FROM public.message_templates OFFSET 0;
CREATE VIEW pulse_read.module_workflow_triggers_v1 WITH (security_barrier = true) AS SELECT module_workflow_trigger_id, company_id, project_id, module_key, event_key, workflow_id, workflow_version_id, enabled, config_json, created_at FROM public.module_workflow_triggers OFFSET 0;
CREATE VIEW pulse_read.project_members_v1 WITH (security_barrier = true) AS SELECT project_id, user_id, role, created_at, client_id, status FROM public.project_members OFFSET 0;
CREATE VIEW pulse_read.projects_v1 WITH (security_barrier = true) AS SELECT project_id, company_id, name, slug, hook_key, created_by_user_id, created_at, updated_at, description, status, priority, start_date, task_workflow_id FROM public.projects OFFSET 0;
CREATE VIEW pulse_read.task_workflow_statuses_v1 WITH (security_barrier = true) AS SELECT task_workflow_status_id, task_workflow_id, name, category, position, is_start, is_done, updated_at FROM public.task_workflow_statuses OFFSET 0;
CREATE VIEW pulse_read.task_workflows_v1 WITH (security_barrier = true) AS SELECT task_workflow_id, project_id, client_id, name, description, is_default FROM public.task_workflows OFFSET 0;
CREATE VIEW pulse_read.tasks_v1 WITH (security_barrier = true) AS SELECT task_id, company_id, project_id, client_id, task_key, title, description, type, task_workflow_status_id, task_workflow_id, priority, assignee_user_id, due_date, archived_at, position, rank, client_visible, billable, labels, updated_at, search_vector FROM public.tasks OFFSET 0;
CREATE VIEW pulse_read.telegram_relay_configs_v1 WITH (security_barrier = true) AS SELECT action_dependency_id, relay_key, public_url, allowed_updates, status, updated_at, polling_enabled, polling_timeout_seconds, polling_limit, polling_next_offset, polling_last_update_id, polling_last_started_at, polling_last_ok_at, polling_last_error, polling_delete_webhook, polling_drop_pending_updates, polling_webhook_deleted_at FROM public.telegram_relay_configs OFFSET 0;
CREATE VIEW pulse_read.users_v1 WITH (security_barrier = true) AS SELECT user_id, email, first_name, created_at, updated_at, display_name FROM public.users OFFSET 0;
CREATE VIEW pulse_read.webhook_events_v1 WITH (security_barrier = true) AS SELECT webhook_event_id, project_id, webhook_endpoint_id, workflow_id, workflow_version_id, workflow_run_id, method, path, payload_json, status, received_at, error FROM public.webhook_events OFFSET 0;
CREATE VIEW pulse_read.workflow_runs_v1 WITH (security_barrier = true) AS SELECT workflow_run_id, project_id, workflow_id, workflow_version_id, source_type, status, started_at, error FROM public.workflow_runs OFFSET 0;
CREATE VIEW pulse_read.workflow_versions_v1 WITH (security_barrier = true) AS SELECT workflow_version_id, project_id, workflow_id, status, definition_json, graph_json, created_by_user_id, created_at FROM public.workflow_versions OFFSET 0;
CREATE VIEW pulse_read.workflows_v1 WITH (security_barrier = true) AS SELECT workflow_id, project_id, name, slug, status, current_workflow_version_id, created_by_user_id, created_at, updated_at, test_input_json FROM public.workflows OFFSET 0;
